pair=json.loads((R/'five-site-kummer-betti-pairing.json').read_text());readout=json.loads((R/'cosmology_physical_readout_source_search.json').read_text());assert pair['betti_representation']=='regular rank-32 orbit of Gamma_+';assert pair['pairing_sheet_basis']=='<e_g,Gamma_h>=delta_(g,h)';blob=json.dumps(pair)
