out={'schema':'marici.benincasa.cosmology-pairing-tau-interface.v1','source_object':'regular rank-32 C2^5 coefficient/Betti sheet pairing','checks':checks,'tau_pairing_composition_defined':False,'first_missing_typed_arrow':'a source-labelled map from the ordered three-wall tau_p quotient to the regular five-sheet coefficient module','dependent_gates':['orientation-authorized cycle in the rank-32 Betti module','period/integral normalization','annihilation of the physical-equivalence kernel'],'decision':'The Kummer pairing is integral, nondegenerate, and deck-covariant on its rank-32 sheet domain, but it cannot be evaluated on tau_p because no three-wall-to-five-sheet domain map is declared. It therefore supplies no integral tau readout.','passed':True};(R/'cosmology_pairing_tau_interface.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
